css:
/* ONE visible game surface, old visual layers retained only as hidden engine nodes. */
html,body{margin:0!important;padding:0!important;background:#07100c!important;overflow:hidden!important}
#app{position:relative!important;max-width:100vw!important;width:100vw!important;height:100dvh!important;max-height:none!important;overflow:hidden!important;transform:none!important;box-shadow:none!important;inset:auto!important;aspect-ratio:auto!important;background:#07100c!important}
#app>:not(#forst-stage){visibility:hidden!important;pointer-events:none!important}
#forst-stage{position:absolute;inset:0;z-index:99999;visibility:visible!important;pointer-events:auto!important;overflow:hidden;background-image:var(--fs-frame);background-size:100% 100%;background-position:center;font-family:Georgia,'Times New Roman',serif;color:#21170f;isolation:isolate}
#forst-stage *,#forst-stage *::before,#forst-stage *::after{box-sizing:border-box}
#forst-stage::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:30;background:linear-gradient(90deg,rgba(10,15,9,.18),transparent 10%,transparent 92%,rgba(9,12,8,.15))}
#fs-banner{position:absolute;left:17%;top:0%;width:68%;height:15.1%;z-index:1;overflow:hidden;cursor:zoom-in;border-bottom:3px ridge #a87638;box-shadow:0 5px 10px #38260e44}
#fs-banner>img{display:block;width:100%;height:100%;object-fit:cover;object-position:center center;filter:saturate(1.14) contrast(1.05)}
#fs-banner::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,transparent 62%,#32251139 100%)}
#fs-beast{position:absolute;left:16%;top:-1%;width:77%;height:35%;z-index:6;pointer-events:none;display:none;overflow:visible;filter:drop-shadow(0 5px 4px #4e311940)}
#fs-beast>img{width:100%;height:100%;object-fit:cover;object-position:center top;-webkit-mask-image:linear-gradient(180deg,#000 0%,#000 77%,transparent 100%);mask-image:linear-gradient(180deg,#000 0%,#000 77%,transparent 100%)}
#forst-stage.fs-combat #fs-banner{opacity:.18;pointer-events:none}
#forst-stage.fs-combat #fs-beast{display:block}
#fs-imgbtn{position:absolute;right:7.5%;top:6.7%;z-index:17;display:flex;flex-direction:column;align-items:center;justify-content:center;width:48px;height:48px;border:2px solid #c69757;border-radius:4px;background:linear-gradient(#292216,#080e0c);box-shadow:0 2px 8px #000a;color:#fff0c9;font:12px Georgia,serif;cursor:pointer;touch-action:manipulation}
#fs-imgbtn>span{font-size:19px;line-height:1.05}
#fs-body{position:absolute;left:16.5%;top:16%;width:77%;height:72%;z-index:8;overflow:visible;display:flex;flex-direction:column;pointer-events:auto}
#forst-stage.fs-combat #fs-body{top:34.5%;height:53.5%}
#fs-body #veil{position:relative!important;display:flex!important;flex:1!important;min-height:0!important;height:100%!important;max-height:none!important;width:100%!important;left:auto!important;top:auto!important;right:auto!important;bottom:auto!important;inset:auto!important;background:none!important;border:0!important;box-shadow:none!important;opacity:1!important;visibility:visible!important;pointer-events:auto!important;overflow:hidden!important;border-radius:0!important;transform:none!important;z-index:2!important;padding:0!important;margin:0!important;filter:none!important}
#fs-body #veil::before,#fs-body #veil::after,#fs-body #veil .sheet::before,#fs-body #veil .sheet::after{display:none!important;content:none!important}
#fs-body #veil .sheet{position:static!important;inset:auto!important;display:flex!important;flex-direction:column!important;width:100%!important;height:100%!important;min-height:0!important;padding:0!important;margin:0!important;max-width:none!important;max-height:none!important;background:transparent!important;border:0!important;box-shadow:none!important;transform:none!important;overflow:hidden!important;filter:none!important}
#fs-body #veil .sheetHead{height:auto!important;min-height:0!important;max-height:none!important;padding:0 5px!important;margin:0!important;flex:0 0 auto!important;background:none!important;box-shadow:none!important;border:0!important;display:block!important}
#fs-body #veil #sheetTitle{font:bold clamp(23px,6.2vw,34px)/1.16 Georgia,serif!important;letter-spacing:0!important;text-align:center!important;color:#211308!important;text-shadow:0 1px #fff4d7b9!important;max-width:100%!important;padding:5px 0 9px!important;margin:0!important;white-space:normal!important;overflow:visible!important}
#fs-body #veil .closeBtn{display:none!important}
#fs-body #veil #sheetBody{position:relative!important;display:block!important;flex:1 1 auto!important;min-height:0!important;max-height:none!important;height:auto!important;width:100%!important;padding:4px 7px 22px!important;margin:0!important;overflow-x:hidden!important;overflow-y:auto!important;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#9a744a transparent;background:none!important;border:0!important;box-shadow:none!important;transform:none!important;color:#26170c!important;font:clamp(16px,4.4vw,19px)/1.55 Georgia,serif!important;-webkit-overflow-scrolling:touch}
#fs-body .parchment,#fs-body .notice,#fs-body .bookCover{position:relative!important;border:0!important;padding:0!important;margin:0 0 15px!important;background:none!important;color:#281a0f!important;box-shadow:none!important;min-height:0!important;max-height:none!important;overflow:visible!important;transform:none!important}
#fs-body .parchment::before,#fs-body .parchment::after{display:none!important}
#fs-body .kicker{font:12px/1.3 Georgia,serif!important;letter-spacing:.06em!important;text-align:center!important;color:#7d5327!important;margin:2px 0 10px!important}
#fs-body .parchment h2,#fs-body .bookCover h2{font:bold clamp(21px,5.6vw,31px)/1.13 Georgia,serif!important;margin:4px 0 16px!important;color:#281509!important;text-align:center!important;text-shadow:none!important}
#fs-body .parchment p,#fs-body .parchment .storyText,#fs-body .bookCover p{font:inherit!important;color:#25170e!important;letter-spacing:0!important;text-shadow:none!important;max-width:100%!important;white-space:pre-line!important;overflow-wrap:break-word!important;line-height:1.55!important}
#fs-body .parchment .storyText{margin:14px 0 20px!important}
#fs-body .bronzeTitle{font:bold clamp(19px,5vw,24px)/1.3 Georgia,serif!important;margin:20px 0 9px!important;color:#291809!important;text-align:left!important}
#fs-body .bronzeTitle::before{content:'──────── ✥ ────────';display:block;text-align:center;color:#9d6829;font:12px Georgia,serif;margin:11px 0}
#fs-body button,#fs-body select{position:relative!important;pointer-events:auto!important;visibility:visible!important;touch-action:manipulation;cursor:pointer}
#fs-body .engraved,#fs-body .minibtn{border:2px ridge #b18a50!important;border-radius:5px!important;background:linear-gradient(145deg,#233a2f,#071a16)!important;color:#fff0cb!important;box-shadow:0 2px 3px #2b170dcc,inset 0 0 0 2px #8b6c35!important;font:16px/1.3 Georgia,serif!important;text-shadow:0 1px 2px #000!important;min-height:44px!important;padding:10px!important;max-width:100%!important;white-space:normal!important}
#fs-body button:active{filter:brightness(1.15);transform:translateY(1px)!important}
#fs-body button:focus-visible,#fs-nav button:focus-visible{outline:3px solid #d7ab55!important;outline-offset:2px}
#fs-body .choices{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important;margin:9px 0 30px!important;padding:0!important;width:100%!important;overflow:visible!important}
#fs-body .storyChoice{display:flex!important;position:relative!important;flex-direction:column!important;justify-content:flex-end!important;min-width:0!important;min-height:144px!important;padding:78px 8px 13px!important;border:3px ridge #b69a58!important;border-radius:6px!important;overflow:hidden!important;background:#051b17!important;box-shadow:0 3px 4px #0008,inset 0 0 0 2px #b6974c!important;color:#fff3d2!important;text-align:center!important}
#fs-body .storyChoice::before{content:""!important;position:absolute!important;z-index:1;pointer-events:none;inset:0;background:linear-gradient(180deg,transparent 28%,rgba(2,18,14,.35) 57%,#001611f0 100%)!important}
#fs-body .storyChoice::after{content:"❯"!important;position:absolute!important;z-index:4;right:3px;bottom:13px;color:#f9c874;text-shadow:0 2px 3px #000;font:bold 19px Georgia,serif}
#fs-body .storyChoice img.choiceArt{position:absolute!important;display:block!important;visibility:visible!important;inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important;opacity:1!important;z-index:0!important;filter:saturate(1.15)}
#fs-body .storyChoice span{position:relative!important;z-index:3!important;display:block!important;padding:0 9px 0 0!important;width:100%!important;text-align:center!important;font:bold clamp(13px,3.5vw,18px)/1.22 Georgia,serif!important;color:#ffeed2!important;text-shadow:0 2px 3px #000,0 1px 5px #000!important}
#fs-body .storyChoice small{display:none!important}
#fs-nav{position:absolute;inset:0;z-index:15;pointer-events:none}
#fs-nav button{pointer-events:auto;position:absolute;border:2px ridge #b99356;background:linear-gradient(#282014,#07110f);color:#ffe8c0;border-radius:4px;text-shadow:0 1px 1px black;box-shadow:0 3px 6px #0008;min-width:47px;min-height:46px;padding:4px;font:12px Georgia,serif;cursor:pointer;touch-action:manipulation}
#fs-nav #fs-trophy{left:1%;top:1.5%;height:50px;width:72px;opacity:0;}
#fs-nav #fs-values{left:1%;bottom:16%;height:50px;width:65px;opacity:0;}
#fs-nav #fs-journal{left:3%;bottom:4%;height:53px;width:65px}
#fs-nav #fs-bag{right:1%;bottom:1%;height:68px;width:22%;min-width:65px;background:transparent;border:none;box-shadow:none;color:transparent;}
#fs-nav #fs-journal strong{display:block;font:21px Georgia,serif;color:#f7d494;line-height:1.0}
#fs-body .sheetBody .creatureCard{max-width:100%!important}
#fs-body .creaturePortrait img{object-fit:cover!important}
#fs-body .combatHud,#fs-body .battleHUD{display:flex!important;flex-wrap:wrap!important;gap:8px!important}
#fs-body #sheetBody .hpBox,#fs-body #sheetBody .combatPanel{color:#23170c!important}
#forst-stage.fs-combat #sheetTitle{margin-top:2px!important}
#forst-stage.fs-home #sheetTitle{padding-top:50px!important}
#forst-stage.fs-combat .battleTitle{font:bold clamp(20px,5.5vw,28px)/1.18 Georgia,serif!important;color:#2c1608!important;text-align:center!important}
#forst-stage.fs-combat #sheetBody{padding-bottom:35px!important}
#forst-stage.fs-combat .combatScene{display:none!important}
#forst-stage.fs-combat .combatActions button{margin:4px 0!important}
#forst-stage.fs-combat #sheetBody .choices{grid-template-columns:repeat(3,minmax(0,1fr))!important}
#fs-fullscreen{position:fixed;inset:0;background:#030906ed;z-index:200000;display:none;align-items:center;justify-content:center;padding:10px}
#fs-fullscreen.open{display:flex}
#fs-fullscreen img{max-width:98vw;max-height:94dvh;object-fit:contain;border:3px ridge #bd9450}
#fs-fullscreen button{position:fixed;right:14px;top:14px;padding:12px 16px;background:#1b2c23;color:#fff2d1;border:2px ridge #ba975c;z-index:1}
@media(max-width:350px){#fs-body{left:16%;width:78%}#fs-body #veil #sheetBody{font-size:16px!important;line-height:1.48!important;padding-left:3px!important;padding-right:3px!important}#fs-body .storyChoice{min-height:130px!important;padding-top:63px!important}#fs-body .storyChoice span{font-size:12px!important}}
@media(max-height:730px){#fs-banner{height:13%}#fs-body{top:14%;height:74%}#forst-stage.fs-combat #fs-body{top:32%;height:56%}#fs-body #veil #sheetTitle{font-size:23px!important;padding:2px 0 6px!important}}

#fs-imgbtn{opacity:0!important;right:5.8%!important;top:5.8%!important;width:65px!important;height:60px!important}
#fs-nav #fs-journal{opacity:0!important;left:2%!important;bottom:3.5%!important;width:72px!important;height:65px!important}
#fs-nav #fs-bag{right:1%!important;bottom:0!important;height:19%!important;width:23%!important}

