(function(){
'use strict';
const app=document.getElementById('app'),veil=document.getElementById('veil');
if(!app||!veil)throw new Error('Game foundation is missing');
const stage=document.createElement('div');stage.id='forst-stage';
const old=document.getElementById('dynamicScene');
stage.innerHTML=`<div id="fs-banner" role="button" tabindex="0" aria-label="Szenenbild vergrößern"><img id="fs-banner-img" alt="Abenteuerillustration"></div><div id="fs-beast"><img id="fs-beast-img" alt="Gegner"></div><button id="fs-imgbtn" title="Bild vergrößern"><span>⛶</span>Bild</button><div id="fs-body"></div><div id="fs-nav"><button id="fs-trophy" title="Trophäen öffnen">Trophäen</button><button id="fs-values" title="Werte öffnen">Werte</button><button id="fs-journal" title="Tagebuch"><strong>▤</strong>Tagebuch</button><button id="fs-bag" aria-label="Inventar öffnen" title="Inventar öffnen">Inventar</button></div><div id="fs-fullscreen" role="dialog" aria-label="Illustration in Großansicht"><button id="fs-close-image">✕ Schließen</button><img id="fs-fullscreen-img" alt="Illustration in groß"></div>`;
app.appendChild(stage);
const img=document.getElementById('fs-banner-img'),foeImage=document.getElementById('fs-beast-img');
stage.style.setProperty('--fs-frame',`url("${FORST_VISUALS.frame}")`);
document.getElementById('fs-body').appendChild(veil);
function setArt(){
 const pic=old?.querySelector('img');
 const k=old?.dataset.scene||'forest_path';
 const val=pic?.getAttribute('src')||SCENE_ART[k]||SCENE_ART.forest_path;
 if(img.src!==val)img.src=val;
 const combat=visiblePanel==='combat';
 if(combat){
 const name=String(state.combat?.name||'').toLowerCase();
 let src;
 if(/wildschwein|eber|keiler/.test(name))src=FORST_VISUALS.boar;
 else{
  const keys=Object.keys(SCENE_ART||{});
  const q=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const match=keys.find(x=>x.toLowerCase().replace(/_/g,' ').includes(q))||keys.find(x=>q.split(' ')[0]&&x.toLowerCase().includes(q.split(' ')[0]));
  src=SCENE_ART[match]||val;
 }
 foeImage.src=src;
 foeImage.alt=name||'Gegner';
 }
}
function sync(){
 if(!stage.isConnected)return;
 stage.classList.remove('fs-home','fs-story','fs-combat','fs-setup');
 stage.classList.add('fs-'+visiblePanel);
 // Refuse accidental rendering of a second window or satchel.
 app.querySelectorAll('#skin-frame,#skin-satchel,#skin-ui-title,#skin-ui-stats,#skin-creature-lunge,#v23-bag-ornament').forEach(n=>n.remove());
 if(visiblePanel==='story'){
 const chapter=veil.querySelector('.storyText');
 if(chapter){
   const raw=chapter.textContent||'';
   const sentinel='\uE000';
   chapter.textContent=raw.replace(/\r/g,'').replace(/\n[ \t]*\n+/g,sentinel).replace(/[ \t]*\n[ \t]*/g,' ').replaceAll(sentinel,'\n\n').replace(/[ \t]{2,}/g,' ');
 }
 const header=veil.querySelector('.parchment h2');
 if(header)document.getElementById('sheetTitle').textContent=header.textContent;
 if(header)header.style.display='none';
 }
 if(visiblePanel==='combat'){
 const bt=veil.querySelector('.battleTitle');
 if(bt){document.getElementById('sheetTitle').textContent=bt.textContent;bt.style.display='none';}
 }
 paintChoices();
 setArt();
}
function paintChoices(){
 const cards=veil.querySelectorAll('button.storyChoice');
 cards.forEach((btn,i)=>{
  const label=btn.textContent.toLowerCase();
  let src=FORST_VISUALS.choiceRuins;
  if(/lichtung|ost|mond|nacht|hain/.test(label))src=FORST_VISUALS.choiceClearing;
  else if(/angreif|schwert|kampf|waffe/.test(label))src=FORST_VISUALS.choiceAttack;
  else if(/flieh|ausweich|flucht/.test(label))src=FORST_VISUALS.choiceDodge;
  else if(/inventar|rucksack|beutel/.test(label))src=FORST_VISUALS.choiceInventory;
  else if(/west|ruine|burg|mauer|turm/.test(label))src=FORST_VISUALS.choiceRuins;
  else if(i%2===1)src=FORST_VISUALS.choiceClearing;
  // Image belongs to the button, not a second layer above the controls.
  btn.style.setProperty('background','linear-gradient(180deg,transparent 5%,rgba(0,15,10,.17) 38%,rgba(0,19,15,.93) 100%),url("'+src+'") center/cover no-repeat','important');
  btn.querySelectorAll('img.choiceArt').forEach(e=>e.remove());
 });
}
const oldRender=renderPanel;
renderPanel=function(){const ret=oldRender.apply(this,arguments);sync();return ret};
const oldScene=showMainScene;
showMainScene=function(){const ret=oldScene.apply(this,arguments);setArt();return ret};
// All buttons call the original book engine; they are not decorative hot spots.
const send=(n)=>{if(typeof openPanel==='function')openPanel(n)};
document.getElementById('fs-trophy').onclick=()=>send('trophies');
document.getElementById('fs-values').onclick=()=>send('stats');
document.getElementById('fs-journal').onclick=()=>send('log');
document.getElementById('fs-bag').onclick=()=>send('pack');
function zoom(){document.getElementById('fs-fullscreen-img').src=visiblePanel==='combat'?foeImage.src:img.src;document.getElementById('fs-fullscreen').classList.add('open')}
function closeZoom(){document.getElementById('fs-fullscreen').classList.remove('open')}
document.getElementById('fs-banner').onclick=zoom;
document.getElementById('fs-imgbtn').onclick=zoom;
document.getElementById('fs-close-image').onclick=closeZoom;
document.getElementById('fs-fullscreen').addEventListener('click',e=>{if(e.target.id==='fs-fullscreen')closeZoom()});
document.getElementById('fs-banner').addEventListener('keydown',e=>{if(e.key==='Enter')zoom()});
renderPanel();
})();
